  ui_story_31210401_74_dialog_content = "Encontró a la monja, le explicó la situación y comenzó a cortejarla una vez más.",
  ui_story_31210401_75_dialog_content = "En su corazón, estaba nervioso, y estaba preparado para que la monja le rechazara de nuevo...",
  ui_story_31210401_76_dialog_content = "Los ojos de la monja se abrieron de par en par, sorprendida, cuando se enteró de que el hombre ya no era un noble...",
