  ui_story_31210401_84_dialog_content = "Es el tipo de palabra que sólo se ve en los cuentos de hadas.",
  ui_story_31210401_85_dialog_content = "Tienes razón. Es un cuento de hadas.",
  ui_story_31210401_86_dialog_content = "¡No pensé que habría una historia tan dramática y detallada en este libro!",
  ui_story_31210401_87_dialog_content = "Pensé que sólo estaría lleno de oscuros mitos antiguos.",
  ui_story_31210401_88_dialog_content = "Si quieres saber más, me temo que tendrás que descubrirlo por ti mismo en el libro.",
