  ui_story_31210401_90_dialog_content = "En ese caso, volveré a leerlo detenidamente...",
  ui_story_31210401_91_dialog_content = "¡Gracias por compartir esa historia, Paloma! ¡Ya te contaré qué me parece el libro cuando termine de leerlo!",
  ui_story_31210401_92_dialog_content = "¡La última vez, me contaste una historia sobre una monja y su familia!",
  ui_story_31210401_93_dialog_content = "Una historia sobre la gracia del Dios de la Luz, la sincera cooperación entre dos familias y un final feliz.",
  ui_story_31210401_94_dialog_content = "Bueno, después de escuchar mi historia, leíste el libro por ti mismo, ¿no es así?",
