  ui_story_31210401_99_dialog_content = "Este libro está lleno de complicadas doctrinas religiosas... Pero me ayudó a dormir.",
  ui_story_31210401_100_dialog_content = "Así es.",
  ui_story_31210401_101_dialog_content = "Y... No entiendo cómo el contenido de este libro tiene algo que ver con la historia que me contaste la última vez.",
