  ui_story_31210401_110_dialog_content = "¿La oscuridad de la realidad?",
  ui_story_31210401_111_dialog_content = "Así que... Esa historia de la última vez no era una simple historia, ¿verdad?",
  ui_story_31210401_112_dialog_content = "Por supuesto que no lo era. Ahora, te revelaré el oscuro final.",
  ui_story_31210401_113_dialog_content = "Volvamos al principio de la \"cooperación\" entre la Familia A y B.",
  ui_story_31210401_114_dialog_content = "Aunque poseían un poder similar, tenían puntos de vista diametralmente opuestos sobre cómo utilizar ese poder.",
  ui_story_31210401_115_dialog_content = "Para lograr su avance mágico, la Familia A cometió un crimen despreciable.",
  ui_story_31210401_116_dialog_content = "Su vergonzoso acto acabó haciéndose público, cuyo impulso fue imposible de apagar.",
  ui_story_31210401_117_dialog_content = "Lumopolis, en nombre del Dios de la Luz, fue castigada, al igual que las Familias A y B.",
  ui_story_31210401_118_dialog_content = "El Dios de la Luz los abandonó, ya que eran indignos de estar en su gloria.",
  ui_story_31210401_119_dialog_content = "Esta historia... me suena familiar...",
  ui_story_31210401_120_dialog_content = "La joven monja de la Familia A no se salvó. Fue excomulgada de la iglesia.",
  ui_story_31210401_121_dialog_content = "Ella pensó que ese sería todo el alcance de su castigo. No esperaba que el destino le jugara una broma aún peor...",
  ui_story_31210401_122_dialog_content = "El hijo de la Familia B era un joven cruel y desquiciado.",
  ui_story_31210401_123_dialog_content = "Cegado por su noble autoridad, juró llegar a cualquier extremo para tener su venganza...",
  ui_story_31210401_124_dialog_content = "Atrajo a todos a sus retorcidas maquinaciones y dio lugar a una tragedia mayor.",
  ui_story_31210401_125_dialog_content = "Los papeles de víctima y victimario siguieron cambiando y girando, y los inocentes se vieron sumidos en un vórtice ineludible.",
  ui_story_31210401_126_dialog_content = "¿Piedad? ¿Comprensión? ¿Perdón? La monja no vio nada de eso. Todo lo que vio fue...",
  ui_story_31210401_A1_dialog_content = "Una crueldad ciega que aplastó su fe.",
  ui_story_31210401_127_dialog_content = "Y así, la monja acató las Escrituras del Templo de Lumopolis, sólo para que su familia fuera asesinada como resultado.",
  ui_story_31210401_128_dialog_content = "Y ahora lo sabes. Ese mismo libro, la misma doctrina—",
  ui_story_31210401_129_dialog_content = "El cuento y realidad tienen finales completamente diferentes. Los cuentos son cuentos, pero la realidad es otra cosa.",
  ui_story_31210401_130_dialog_content = "Y eso es todo lo que hay que decir sobre este libro.",
  ui_story_31210401_131_dialog_content = "Las Escrituras del Templo de Lumopolis...",
  ui_story_31210401_132_dialog_content = "Tienes una mirada muy extraña en este momento... Dime qué tienes en mente.",
  ui_story_31210401_133_dialog_content = "Creo que veo lo que estás tratando de decir, Paloma. Esa monja en realidad...",
  ui_story_31210401_134_option_content = "¿No ha encontrado su propia fe verdadera aún...?",
  ui_story_31210401_135_dialog_content = "Quizás.",
  ui_story_31210401_136_dialog_content = "Pero entender que las creencias anteriores eran erróneas no es del todo malo.",
  ui_story_31210401_137_dialog_content = "¿La tragedia de su pasado fue demasiado para la monja?",
  ui_story_31210401_138_option_content = "¿Has encontrado tu verdadera fe?",
  ui_story_31210401_139_dialog_content = "¿Realmente crees que existe la verdadera fe en este mundo?",
  ui_story_31210401_140_dialog_content = "Lo siento.. no lo sé.",
  ui_story_31210401_141_dialog_content = "Eso no es importante.",
  ui_story_31210401_142_dialog_content = "Lo importante es que la fe no debe ser un dispositivo utilizado por unos pocos para lavar el cerebro de la mayoría.",
  ui_story_31210401_143_dialog_content = "La fe debe venir de adentro.",
  ui_story_31210401_144_dialog_content = "Desde adentro...",
  ui_story_31210401_145_dialog_content = "La realidad del Templo de Lumopolis es mucho más corrupta de lo que podrías imaginar.",
  ui_story_31210401_146_dialog_content = "Aferrándose a un sistema de clases en decadencia que no se puede cruzar en la vida de un individuo.",
  ui_story_31210401_147_dialog_content = "Tal vez... ¿el templo es sólo una parte de Lumopolis?",
  ui_story_31210401_148_dialog_content = "Me he encontrado tanto con plebeyos ignorantes como con nobles de principios en Lumopolis.",
  ui_story_31210401_149_dialog_content = "Lumopolis es una ciudad vasta y compleja. Hay mucha gente en ella.",
  ui_story_31210401_A2_dialog_content = "No sólo un único e intangible Dios de la Luz.",
  ui_story_31210401_150_dialog_content = "Sé que algunos no están contentos con el estado de las cosas e intentan hacer algo al respecto...",
  ui_story_31210401_151_dialog_content = "... Entiendo tu forma de pensar.",
  ui_story_31210401_152_dialog_content = "Pero lo siento.",
  ui_story_31210401_153_dialog_content = "Los que creen que Lumopolis puede cambiar no perciben el núcleo del problema.",
  ui_story_31210401_154_dialog_content = "Su estructura innata crea una contradicción irreconciliable.",
  ui_story_31210401_155_dialog_content = "Pero cada uno tiene derecho a su propia opinión... A esto, no puedo objetar.",
  ui_story_31210401_156_dialog_content = "Por lo tanto, mantén tu visión del mundo.",
  ui_story_31210401_157_dialog_content = "Erm... ¿Ya te vas?",
  ui_story_31210401_158_dialog_content = "¡Espera, se te cayó la moneda!",
  ui_story_31210401_159_dialog_content = "Quédate con ella. Me gustaría dártela como recuerdo de esta conversación.",
  ui_story_31210401_160_dialog_content = "Adiós.",
  ui_story_31210601_1_dialog_content = "¿Es este el lugar?",
  ui_story_31210601_2_dialog_content = "Así es, ahora entremos.",
  ui_story_31210601_3_dialog_content = "Con respecto a Pittman, ya hice arreglos. ¿Realmente vamos a hacer esto?",
  ui_story_31210601_4_dialog_content = "Por supuesto. Después de todo, como el segundo al mando de la <color=#FFB400>Rosas negras</color>, esto también es parte de tu trabajo.",
  ui_story_31210601_5_dialog_content = "En cuanto a lo que pasa si no cumples tu palabra... Bueno, creo que te lo he dejado perfectamente claro, ¿no?",
  ui_story_31210601_6_dialog_content = "C-Cristal claro. Sólo déjamelo a mi.",
  ui_story_31210601_7_dialog_content = "Por favor, límpiese las manos primero, señor.",
  ui_story_31210601_8_dialog_content = "Está bien.",
  ui_story_31210601_9_dialog_content = "(Ahora todo lo que tengo que hacer es arrancar una uva y dársela a Paloma).",
  ui_story_31210601_10_dialog_content = "(Ya lo he ensayado en mi mente un montón de veces, pero todavía se siente incómodo...)",
  ui_story_31210601_11_dialog_content = "¿Bien? ¿Que estas esperando?",
  ui_story_31210601_12_dialog_content = "(¡¿E-Me agarró la mano...?!)",
  ui_story_31210601_13_dialog_content = "(Ella solo se está alimentando en este punto...)",
  ui_story_31210601_14_dialog_content = "Nunca llegarás a ser mi segundo al mando con una disposición tan rígida.",
  ui_story_31210601_15_dialog_content = "Lo haré mejor la próxima vez.",
  ui_story_31210601_16_dialog_content = "¡¿Por qué están parados alrededor boquiabiertos?! ¿No tienen todos ustedes trabajo que hacer?",
  ui_story_31210601_17_dialog_content = "¡S-Sí!",
  ui_story_31210601_18_dialog_content = "Utilice este pañuelo para limpiarse las manos.",
  ui_story_31210601_19_dialog_content = "Y aquí hay una copa de vino. Por favor, disfruta.",
  ui_story_31210601_20_dialog_content = "Ahora que es más como él. Serás un maravilloso segundo al mando a este ritmo, PlayerName.",
  ui_story_31210601_21_dialog_content = "Lo tomaré como un cumplido...",
  ui_story_31210601_22_dialog_content = "Muy bien, eso servirá por ahora. No deberíamos hacer esperar más a nuestro invitado.",
  ui_story_31210601_23_dialog_content = "Hmph. Casi no te reconozco, Paloma.",
  ui_story_31210601_24_dialog_content = "Unirse a una pandilla sin pensarlo dos veces simplemente como un desafío contra Lumopolis. ¿No hay límite para lo bajo que estás dispuesto a rebajarte?",
  ui_story_31210601_25_dialog_content = "No olvides que sigues siendo un criminal buscado.",
  ui_story_31210601_26_dialog_content = "Soy libre de hacer lo que quiera y unirme al grupo que crea conveniente.",
  ui_story_31210601_27_dialog_content = "Además, Lumopolis es lo peor de lo peor de este mundo. ¡Cualquiera estaría un paso por encima de ellos!",
  ui_story_31210601_28_dialog_content = "Dime, ¿tu lacayo me trajo aquí solo para que pudieras regodearte con un viejo conocido de lo irreconocible que te has vuelto?",
  ui_story_31210601_29_dialog_content = "Te dije la última vez que no te mostraría piedad si alguna vez nos volvíamos a encontrar.",
  ui_story_31210601_30_dialog_content = "Tiene un concepto demasiado elevado de sí mismo, Su Señoría. Claramente, eres tú quien ha estado persiguiendo mis talones todo este tiempo.",
  ui_story_31210601_31_dialog_content = "Estaba dispuesto a dejarte ir, pero como nos has traído hasta este punto, parece que no tengo otra opción.",
  ui_story_31210601_32_dialog_content = "Que este sea el lazo final con Lumopolis que corte. Buen viaje.",
  ui_story_31210601_33_dialog_content = "Aún así, no tengo ninguna razón para tratar personalmente con alguien de tu nivel.",
  ui_story_31210601_34_dialog_content = "Haré que mi segundo al mando te muestre exactamente lo que sucede cuando te conviertes en mi enemigo.",
  ui_story_31210601_35_dialog_content = "¿Listo para lo peor, Su Señoría?",
  ui_story_31210601_36_dialog_content = "¿Tiene la intención de enviar a un solo compinche a luchar contra un juez de Lumopolis?",
  ui_story_31210601_37_dialog_content = "¿Crees que eres tan duro, eh? Perdona mi insolencia entonces.",
  ui_story_31210601_38_dialog_content = "Urgh—!",
  ui_story_31210601_39_dialog_content = "Está inconsciente, jefe.",
  ui_story_31210601_40_dialog_content = "Ni siquiera podría tomar un solo golpe, ¿eh? ¡Qué monstruosidad!",
  ui_story_31210601_41_dialog_content = "Átalo y tráelo conmigo.",
  ui_story_31210601_42_dialog_content = "¡Sí, señora!",
  ui_story_31210601_43_dialog_content = "Genial... simplemente genial! ¡Jajaja!",
  ui_story_31210601_44_dialog_content = "Tu fuerza y tu astucia me avergüenzan incluso a mí, Lady Paloma.",
  ui_story_31210601_45_dialog_content = "Me halagas. Me alegro de que mi actuación no te haya decepcionado.",
  ui_story_31210601_46_dialog_content = "¿Cómo podría haberlo hecho? Las Rosas Negras realmente deben ser algo, considerando que incluso un segundo al mando podría derribar a un juez.",
  ui_story_31210601_47_dialog_content = "Aunque nunca he oído hablar de tu pandilla, espero ver tus hazañas en un futuro cercano.",
  ui_story_31210601_48_dialog_content = "Los Black Roses siempre han sido tan agresivos como discretos.",
  ui_story_31210601_49_dialog_content = "¿No es esta la razón por la que te acercaste a nosotros en primer lugar?",
  ui_story_31210601_50_dialog_content = "Ah... Su mente perceptiva y su lengua rápida solo se comparan con su belleza, milady.",
  ui_story_31210601_51_dialog_content = "Para ser honesto, mi enemistad con el Salón de la Justicia se remonta a muchos años. Siempre han estado dispuestos a oprimir a los demás con sus reglas sin sentido, incluso a su propia gente.",
  ui_story_31210601_52_dialog_content = "Usted mismo lo escuchó hace un momento también. El Salón de la Justicia ha puesto una recompensa por mi cabeza.",
  ui_story_31210601_53_dialog_content = "Teniendo en cuenta nuestro enemigo común, creo que podemos trabajar juntos muy bien.",
  ui_story_31210601_54_dialog_content = "Sería mi mayor honor hacerlo.",
  ui_story_31210601_55_dialog_content = "Agradecemos sus elogios, pero vayamos al grano, ¿de acuerdo? Cuéntame más sobre este trabajo tuyo.",
  ui_story_31210601_56_dialog_content = "Directo al grano, me gusta!",
  ui_story_31210601_57_dialog_content = "Me gustaría pedir ayuda a su organización para \"purgar\" un área bajo mi jurisdicción.",
  ui_story_31210601_58_dialog_content = "Una vez que termines tu trabajo, llegaré con un séquito de soldados, fingiremos una batalla y luego mis hombres te dejarán ir.",
  ui_story_31210601_59_dialog_content = "Luego, regresaremos a Lumopolis para tratar nuestras heridas. Una vez allí, afirmaré que mi dominio fue atacado por Eclipsites y que casi fuimos aniquilados.",
  ui_story_31210601_60_dialog_content = "¿Quieres purgar tu propio territorio de su gente?",
  ui_story_31210601_61_dialog_content = "¿Por qué te harías algo así a ti mismo?",
  ui_story_31210601_62_dialog_content = "Ese páramo yermo no tiene futuro como lo es ahora. Estar atado a él solo me retrasará.",
  ui_story_31210601_63_dialog_content = "Ya tengo en la mira una parcela de tierra fértil, pero sigue en manos de un opositor político. Con este plan, el Señor de la Ciudad no tendrá más remedio que interceder por mí.",
  ui_story_31210601_64_dialog_content = "Será el último propósito que esos tontos me servirán.",
  ui_story_31210601_66_dialog_content = "<color=#e8d9bb>Sonido metálico seco-</color>",
  ui_story_31210601_67_dialog_content = "Considere este cofre de joyas como su pago por adelantado.",
  ui_story_31210601_68_dialog_content = "Si tiene éxito, podría convertirlo en un oficial honorario en la ciudad después si lo desea.",
  ui_story_31210601_69_dialog_content = "La ley estaría de tu lado una vez más; ya no tendrías que vivir en las sombras.",
  ui_story_31210601_70_dialog_content = "Tampoco tendrías que trabajar un día más. ¡Las ofrendas de la gente serían más que suficientes para mantenernos a todos por el resto de nuestras vidas!",
  ui_story_31210601_71_dialog_content = "¿Qué dices? Creo que una oferta como esta requiere muy poca consideración.",
  ui_story_31210601_72_dialog_content = "Puedes olvidarte de convertirme en oficial. Siempre he hecho mi trabajo de acuerdo a lo que me pagan.",
  ui_story_31210601_73_dialog_content = "Además, no tengo ningún interés en establecer ningún tipo de vínculo con Lumopolis o sus podridos sistemas de gobierno.",
  ui_story_31210601_74_dialog_content = "Realmente eres diferente al resto. Pues bien, dejo mi brillante y próspero futuro en manos de las Rosas Negras.",
  ui_story_31210601_75_dialog_content = "Vosotros, hipócritas nobles de Lumopolis, deberíais confiar vuestro futuro al Dios de la Luz, no a mí.",
  ui_story_31210601_76_dialog_content = "No hay nada especial en mí.",
  ui_story_31210601_77_dialog_content = "¿Fue algo que dije? ¿O tal vez algo de mi oferta no fue de su agrado?",
  ui_story_31210601_78_dialog_content = "Oh no, tu oferta fue bastante razonable. Más que suficiente para asegurarme un futuro brillante y próspero, de hecho.",
  ui_story_31210601_79_dialog_content = "Desafortunadamente, el único futuro que te espera está en una celda de prisión del Salón de la Justicia.",
  ui_story_31210601_80_dialog_content = "¡¿Qué?! Tú... ¡¿Cuál es el significado de esto?!",
  ui_story_31210601_81_dialog_content = "¡Ah, ya veo! ¡Lo entiendo todo ahora! ¡Ustedes dos mestizos estuvieron trabajando juntos todo el tiempo para implicarme! ¡¿Es asi?!",
  ui_story_31210601_82_dialog_content = "¡Sí, ahora lo recuerdo! La última vez, cuando les estaba dando una lección a esos plebeyos, tú eras la \"monja\" que me atacó, ¿no? ¡La rosa negra!",
  ui_story_31210601_83_dialog_content = "Un disfraz tan brillante. Ni siquiera te reconocí.",
  ui_story_31210601_84_dialog_content = "En cuanto a usted, Su Señoría... ¿Usted fue quien evitó que me atacara, si no me equivoco?",
  ui_story_31210601_85_dialog_content = "Y pensar que ustedes dos trabajaron juntos todo este tiempo solo para atraparme...",
  ui_story_31210601_86_dialog_content = "Usted malinterpreta la profundidad de nuestra cooperación.",
  ui_story_31210601_87_dialog_content = "Solo la detuve en ese momento porque, a pesar de tu vil comportamiento, no habías violado las leyes de Lumopolis.",
  ui_story_31210601_88_dialog_content = "Tengo la obligación de proteger a los ciudadanos legítimos de Lumopolis, incluyéndote a ti. Mis acciones ese día no fueron ensayadas de ninguna manera.",
  ui_story_31210601_89_dialog_content = "En ese sentido, deberías saber... No existe tal organización como la \"Rosa Negra\", y yo no soy el jefe de una pandilla.",
  ui_story_31210601_90_dialog_content = "En cuanto a mis \"secuaces\", si estuvieras prestando más atención, podrías haber reconocido algunas de sus caras.",
  ui_story_31210601_91_dialog_content = "Después de aprovecharse de nosotros durante tanto tiempo... ¿No nos digas que no recuerdas cómo nos vemos?",
  ui_story_31210601_92_dialog_content = "Tu gente...",
  ui_story_31210601_93_dialog_content = "Todas son personas de tu dominio. Tu gente.",
  ui_story_31210601_94_dialog_content = "Maldita sanguijuela... ¡Tú eres el que chupó la vida de nuestras tierras!",
  ui_story_31210601_95_dialog_content = "¡Olvídate de nuestro hogar, ni siquiera te importan nuestras vidas! ¡Hoy te enseñaremos una lección que nunca olvidarás!",
  ui_story_31210601_96_dialog_content = "Rubíes sin dinero... ¡Deberían estar agradecidos por la oportunidad de trabajar para mí!",
  ui_story_31210601_97_dialog_content = "Si estás tan desesperado por pelear, ¡permíteme que te devuelva a tu lugar!",
  ui_story_31210601_98_dialog_content = "¡Hombres! ¡A mi!",
  ui_story_31210601_99_dialog_content = "\"Hombres\"? ¿Te refieres a estos tontos lamentables?",
  ui_story_31210601_100_dialog_content = "Lamento decepcionarte, pero han estado ocupados por un tiempo.",
  ui_story_31210601_101_dialog_content = "(Maldita sea... ¡Maldita sea! ¡No puede terminar así! Debe haber una manera...)",
  ui_story_31210601_102_dialog_content = "¡Espere, Su Señoría! Seguramente, no tienes nada que hacer con una mujer loca como ella.",
  ui_story_31210601_103_dialog_content = "¡Ayúdame a salir de este lugar a salvo, y haré todo lo que esté a mi alcance para impulsarte en las filas!",
  ui_story_31210601_104_dialog_content = "¡Incluso la posición del juez principal no está fuera de discusión!",
  ui_story_31210601_105_dialog_content = "¿Vaya? Qué cambio tan repentino de postura.",
  ui_story_31210601_106_dialog_content = "¿No es tu deber proteger la seguridad y la prosperidad de los nobles Lumo?",
  ui_story_31210601_107_dialog_content = "¡Esta podría ser tu oportunidad de mostrarnos tu lealtad inquebrantable! ¡Piénsalo!",
  ui_story_31210601_108_dialog_content = "Mientras no te ataquen, no tengo motivos para interferir.",
  ui_story_31210601_109_dialog_content = "Además, siento que debo corregir una de sus afirmaciones.",
  ui_story_31210601_110_dialog_content = "Mi lealtad inquebrantable es al Dios de la Luz, y mi deber es defender la justicia y el orden en Lumopolis, no los intereses de la clase noble.",
  ui_story_31210601_111_dialog_content = "¡¿De qué estás hablando?! ¡Claramente me amenazaron hace un momento! ¡¿No estabas escuchando?!",
  ui_story_31210601_112_dialog_content = "¿O es esta \"justicia\" a la que ustedes juzgan les encanta hablar de nada más que formalidades vacías?",
  ui_story_31210601_113_dialog_content = "Estabas seguro de hacer comentarios groseros hacia tus propios ciudadanos antes, ¿no?",
  ui_story_31210601_114_dialog_content = "La ley se aplica a todos por igual, y esta situación no es diferente.",
  ui_story_31210601_115_dialog_content = "¡No eres menos hipócrita que yo! Especialmente tú, Paloma... ¡Eres la peor de todas!",
  ui_story_31210601_116_dialog_content = "Hablas de odiar a Lumopolis con todo tu corazón, ¡pero estás dispuesto a conspirar con uno de sus jueces!",
  ui_story_31210601_117_dialog_content = "Estoy dispuesto a reconocer mi propia hipocresía. ¿Eres?",
  ui_story_31210601_118_dialog_content = "¡Hmph—!",
  ui_story_31210601_119_dialog_content = "No soy nada como tú. Actuar cortés y amable frente a la nobleza, mientras trata a los plebeyos sin una pizca de decencia.",
  ui_story_31210601_120_dialog_content = "Y nunca dije que lo que hice hoy fuera para el juez de Lumopolis. Lo hice todo por mí mismo.",
  ui_story_31210601_121_dialog_content = "Tus acciones me enfermaron del estómago ese día, así que elegí tratar contigo. Es tan simple como eso.",
  ui_story_31210601_121X1_dialog_content = "Si PlayerName Si no me lo hubiera dicho antes, habría creído que realmente te uniste a una pandilla.",
  ui_story_31210601_122_dialog_content = "<color=#e8d9bb>Unas horas antes...</color>",
  ui_story_31210601_123_dialog_content = "pittman! ¡Aqui!",
  ui_story_31210601_124_dialog_content = "¿PlayerName? ¿Qué estás haciendo aquí?",
  ui_story_31210601_125_dialog_content = "¿Y por qué estás vestido como un pandillero?",
  ui_story_31210601_126_dialog_content = "¡No hay tiempo para explicar! ¡Solo ven conmigo! ¡Apuro!",
  ui_story_31210601_127_dialog_content = "¡E-Espera! ¡Todavía tengo asuntos urgentes que atender!",
  ui_story_31210601_128_dialog_content = "Hace unos días, un noble de Lumopolis se cruzó en el camino de Paloma, y apenas logré intervenir antes de que la situación empeorara.",
  ui_story_31210601_129_dialog_content = "Pero después, no parecía que Paloma estuviera lista para dejar el asunto... Me preocupa que esté a punto de hacer algo terrible.",
  ui_story_31210601_130_dialog_content = "Por eso no puedo ir contigo ahora. Por favor perdoname.",
  ui_story_31210601_131_dialog_content = "¡Paloma es la que me pidió que fuera a buscarte, Pittman!",
  ui_story_31210601_132_dialog_content = "¡Ah, y no lo olvides! Tienes que fingir que te noqueo más tarde; ¡haz que parezca real para que no parezca un acto!",
  ui_story_31210601_133_dialog_content = "¿Quieres que actúe...? No entiendo muy bien... ¿Esto es algo que cocinó Paloma?",
  ui_story_31210601_134_dialog_content = "¡No te preocupes por eso! Lo entenderás todo una vez que veas lo que sucede entre Paloma y ese noble, ¿de acuerdo?",
  ui_story_31210601_135_dialog_content = "¡Ella no hará nada ilegal, lo prometo! Yo confío en ella, y tú confías en mí... ¿Cierto?",
  ui_story_31210601_136_dialog_content = "A pesar de que me había preparado mentalmente, todavía estaba un poco sorprendido en el momento en que entré.",
  ui_story_31210601_137_dialog_content = "¿En serio? Tú que tal, PlayerName?",
  ui_story_31210601_138_option_content = "Todo es gracias a tu disfraz.",
  ui_story_31210601_139_dialog_content = "Ese atuendo realmente enfatiza tu presencia genial e imponente.",
  ui_story_31210601_140_dialog_content = "¡Aunque estaba parado junto a ti, podría haber jurado que estaba parado junto a un verdadero jefe de pandilla!",
  ui_story_31210601_141_option_content = "Tu personalidad llevó el espectáculo.",
  ui_story_31210601_142_dialog_content = "Parecía que habías nacido para interpretar al líder de las Rosas Negras.",
  ui_story_31210601_143_dialog_content = "¡Incluso a mí me costó recordar que no eras un líder de pandilla vicioso!",
  ui_story_31210601_144_dialog_content = "No ayuda que este atuendo parezca sacado directamente de tu guardarropa personal.",
  ui_story_31210601_145_dialog_content = "Hmph. Estás empezando a sonar como un compinche real con toda esa adulación.",
  ui_story_31210601_146_dialog_content = "Sin embargo, tengo que decir... que ese atuendo también te sienta bien, PlayerName.",
  ui_story_31210601_147_dialog_content = "¿Estás seguro de que no quieres quedarte como mi mano derecha?",
  ui_story_31210601_148_dialog_content = "¡¿E-Eh?!",
  ui_story_31210601_149_dialog_content = "*Riéndose* Solo estoy bromeando.",
  ui_story_31210601_150_dialog_content = "Además, trabajo mejor solo. Nunca haría algo tan estúpido o problemático como unirme a una pandilla.",
  ui_story_31210601_151_dialog_content = "El hecho de que nunca hayas tenido la intención de atacar a ese noble demuestra que has madurado bastante, Paloma.",
  ui_story_31210601_152_dialog_content = "¿Quien lo? Por favor, era un blanco fácil. Además, no tenía ganas de ensuciarme las espinas.",
  ui_story_31210601_153_dialog_content = "Aunque estoy igual de sorprendido de que alguien tan terco y entrometido como tú se haya quedado quieto a un lado mientras todo sucedía. Tú también has madurado un poco, Pittman.",
  ui_story_31210601_154_dialog_content = "Simplemente elegí confiar en ti y PlayerName esta vez... así como mi propia habilidad para responder rápidamente, si la situación lo requería.",
  ui_story_31210601_155_dialog_content = "Además, no tenía ningún deseo de arrestarte yo mismo, por lo que no te habría dejado hacer nada ilegal frente a mí.",
  ui_story_31210601_156_dialog_content = "Mucha confianza en sí mismo, ¿no es así, Su Señoría?",
  ui_story_31210601_157_dialog_content = "Esas personas afuera vestidas de blanco deben ser del Salón de la Justicia.",
  ui_story_31210601_158_dialog_content = "Sus refuerzos llegaron más rápido de lo que pensaba.",
  ui_story_31210601_159_dialog_content = "Ella no estaba bromeando. ¡La calle está llena de Lumo Guards!",
  ui_story_31210601_160_dialog_content = "¿Quieres decir que no los llamaste?",
  ui_story_31210601_161_dialog_content = "No, no lo hice. ¿Acaso tú?",
  ui_story_31210601_162_dialog_content = "¿Era ella?",
  ui_story_31210601_163_dialog_content = "Paloma se ha ido...",
  ui_story_31210601_164_dialog_content = "Así que... esta es la Rosa Negra, ¿eh?",
  ui_story_31210601_165_dialog_content = "Cuánto me parezco a ella.",
  ui_story_31210602_1_dialog_content = "Ah... esos ojos luminiscentes, el rostro regalado por los dioses... ¡es como contemplar a una deidad!",
  ui_story_31210602_2_dialog_content = "¡Qué espléndido, la deidad que venero... mi diosa...!",
  ui_story_31210602_3_dialog_content = "Ah... ¡Qué refrescante es la brisa marina!",
  ui_story_31210602_4_dialog_content = "EveCada vez que voy a la playa, me siento tan feliz. Entonces, ¿qué hago ahora?",
  ui_story_31210602_5_option_content = "Recoge conchas hermosas",
  ui_story_31210602_6_dialog_content = "Podría ser capaz de decorar el Coloso con algunas de estas hermosas conchas.",
  ui_story_31210602_7_dialog_content = "Hay bastantes aquí. Parece que he dado en el clavo.",
  ui_story_31210602_8_option_content = "Recuéstate en la arena",
  ui_story_31210602_9_dialog_content = "La arena aquí es tan delicada y suave, no puedo evitar querer recostarme en ella.",
  ui_story_31210602_10_dialog_content = "¿Eh? ¿Qué es esta espina negra en la arena? Alguien podría lastimarse con ella... Supongo que debería sacarla.",
  ui_story_31210602_11_dialog_content = "¿Qué estás haciendo?",
  ui_story_31210602_12_dialog_content = "¡Vaya?! ¿Qué estabas haciendo ahí abajo en la arena?",
  ui_story_31210602_13_dialog_content = "Solo estaba aquí acostado disfrutando del sol hasta que empezaste a tirar de mi traje de baño.",
  ui_story_31210602_14_dialog_content = "S-Lo siento, pensé que era algún tipo de púa...",
  ui_story_31210602_15_dialog_content = "Si realmente quieres disculparte, me gustaría que me acompañaras a algún lugar.",
  ui_story_31210602_16_dialog_content = "Eh... ¿Dónde?",
  ui_story_31210602_17_dialog_content = "¿Has oído hablar de la misteriosa secta aquí que adora a la Diosa del Espino de Fuego?",
  ui_story_31210602_18_dialog_content = "¿La Diosa del Espino Ardiente? Nunca oído hablar de ella.",
  ui_story_31210602_19_dialog_content = "La gente mundana simplemente adora crear esos falsos dioses pequeños.",
  ui_story_31210602_20_dialog_content = "La inteligencia que he adquirido indica que algo está mal en esta secta, y planeo investigarlo.",
  ui_story_31210602_21_dialog_content = "Eso suena algo peligroso. Iré contigo.",
  ui_story_31210602_22_dialog_content = "Pero antes de irnos, necesito cambiarme a mi ropa normal.",
  ui_story_31210602_23_dialog_content = "Oye, ¿qué creen que están haciendo ustedes dos? ¡Los extraños no son bienvenidos aquí! ¡Fuera con ustedes!",
  ui_story_31210602_24_dialog_content = "<size=30>¿Qué hacemos ahora? No nos dejarán entrar...</size>",
  ui_story_31210602_25_dialog_content = "<size=30>No te preocupes, déjame esto a mí.</size>",
  ui_story_31210602_26_dialog_content = "Somos nuevos miembros del rebaño y nos gustaría participar en la ceremonia de hoy.",
  ui_story_31210602_27_dialog_content = "Sangre nueva, ¿eh? ¿Tienes alguna prueba? ¿Llevas el sello de la Diosa del Espino de Fuego?",
  ui_story_31210602_28_dialog_content = "¿El símbolo de la Diosa del Espino de Fuego?",
  ui_story_31210602_29_dialog_content = "Esto—",
  ui_story_31210602_30_dialog_content = "(Él acaba de sacar un trozo corto de espina afilada. Supongo que se acabó el juego, ¡no hay forma de que pasemos desapercibidos ante él!)",
  ui_story_31210602_31_dialog_content = "¿Es esto de lo que estás hablando?",
  ui_story_31210602_32_dialog_content = "(¿Eh? ¿Paloma en realidad tiene uno de esos?)",
  ui_story_31210602_33_dialog_content = "Eso es correcto. Este es el don otorgado por la Diosa del Espino de Fuego, un regalo que solo los verdaderos creyentes pueden poseer.",
  ui_story_31210602_34_dialog_content = "Deberías habérmelo mostrado antes. Puedes ingresar.",
  ui_story_31210602_35_dialog_content = "¿Cómo conseguiste ese símbolo?",
  ui_story_31210602_36_dialog_content = "Adivina.",
  ui_story_31210602_37_dialog_content = "Lo lograste con tus poderes.",
  ui_story_31210602_38_dialog_content = "Supongo que después de todo no eres tan aburrido.",
  ui_story_31210602_39_dialog_content = "Es una coincidencia que puedas manipular espinas... Es bueno que el símbolo no fuera una barra de chocolate.",
  ui_story_31210602_40_dialog_content = "¿Realmente crees que fue una coincidencia?",
  ui_story_31210602_41_dialog_content = "¿Qué?",
  ui_story_31210602_42_dialog_content = "Parece que la ceremonia aún no ha comenzado. Busquemos un lugar donde podamos verla desde las sombras.",
  ui_story_31210602_43_dialog_content = "Está tan oscuro aquí. Pensé que todas las ceremonias religiosas tenían lugar en espacios abiertos y luminosos.",
  ui_story_31210602_44_dialog_content = "No todas las iglesias siguen la luz. Quizás solo encontremos misteriosas invocaciones y ofrendas aquí, o tal vez incluso sacrificios...",
  ui_story_31210602_45_dialog_content = "No me asustes, no quiero ser servido como un cordero en el altar.",
  ui_story_31210602_46_dialog_content = "No te preocupes. Esta chusma aún no tiene el valor de sacrificar a los vivos.",
  ui_story_31210602_47_dialog_content = "Verdaderos creyentes, bienvenidos a la ceremonia de hoy. Soy el mensajero del Pastor.",
  ui_story_31210602_48_dialog_content = "Hoy, ofrecemos nuestro sacrificio más preciado a la Diosa del Espino de Fuego, una expresión de nuestro amor y admiración por ella.",
  ui_story_31210602_49_dialog_content = "¡Alabemos a la Diosa del Espino Ardiente! ¡Alabemos al Pastor!",
  ui_story_31210602_50_dialog_content = "Veo que tenemos algunas caras nuevas entre nosotros hoy. Por supuesto, damos la bienvenida a la incorporación de sangre fresca, pero primero tendrán que presentarnos sus ofrendas.",
  ui_story_31210602_51_dialog_content = "Solo después de ser aprobado por nuestros árbitros puedes unirte oficialmente a nosotros.",
  ui_story_31210602_52_dialog_content = "¿Qué tipo de ofrendas? No nos van a hacer nada, ¿cierto?",
  ui_story_31210602_53_dialog_content = "Veamos qué hacen los demás primero.",
  ui_story_31210602_54_dialog_content = "¡Tengo una oferta! ¡Quiero presentarla!",
  ui_story_31210602_55_dialog_content = "Un acólito apasionado. ¡Excelente! Por favor, únete a mí en el escenario.",
  ui_story_31210602_56_dialog_content = "Esta es una foto que tomé de una estrella de mar. Creo que es muy hermosa y perfecta para expresar mi respeto por la Diosa del Espino de Fuego.",
  ui_story_31210602_57_dialog_content = "¿Un estrella de mar? ¿Deseas ofrecer una estrella de mar a la Diosa Espino de Fuego? ¿Crees que una simple estrella de mar tocaría su corazón?",
  ui_story_31210602_58_dialog_content = "Uh, en realidad, creo que la estrella de mar que fotografió es realmente linda.",
  ui_story_31210602_59_dialog_content = "¿Has olvidado el enfoque de nuestras enseñanzas actuales? ¿Realmente crees que al Pastor le gustaría ver algo tan mediocre y poco interesante? Siguiente.",
  ui_story_31210602_60_dialog_content = "Hola a todos. La foto que quiero compartir con ustedes es de una tortuga marina, que es un tipo de...",
  ui_story_31210602_61_dialog_content = "Cero puntos.",
  ui_story_31210602_62_dialog_content = "Cero puntos.",
  ui_story_31210602_63_dialog_content = "Cinco puntos. Es un gran tiro. Las tortugas tienen una vida muy larga. Deben guardar muchas historias y misterios.",
  ui_story_31210602_64_dialog_content = "Las tortugas son solo reptiles lentos y aburridos. Puedes conseguir estas fotos en cualquier lugar. No tienen valor.",
  ui_story_31210602_65_dialog_content = "Éramos un club de fotografía de biología marina, y aunque ahora somos un—",
  ui_story_31210602_66_dialog_content = "¡Tranquilo! ¡Siguiente!",
  ui_story_31210602_67_dialog_content = "Algunos de estos jueces son realmente duros, pero hasta ahora, parece que esta iglesia es básicamente solo un grupo de fotógrafos de vida marina.",
  ui_story_31210602_68_dialog_content = "Cada uno posee un pequeño trozo de espino de fuego. ¿Qué, por favor dime, tiene esto que ver con las criaturas marinas?",
  ui_story_31210602_69_dialog_content = "Bueno... Supongo que no hay conexión ahí.",
  ui_story_31210602_70_dialog_content = "Entonces, definitivamente hay algo más profundo ocurriendo con esta secta.",
  ui_story_31210602_71_dialog_content = "De todos modos, la diversión está a punto de comenzar.",
  ui_story_31210602_72_dialog_content = "¿Quieres decir?",
  ui_story_31210602_73_dialog_content = "Las luces se han atenuado, las puertas se han cerrado y la vela azul encendida... Ah, esta falsa ceremonia de bendita chicanería está a punto de comenzar.",
  ui_story_31210602_74_dialog_content = "¡El gran Pastor ha llegado, demosle la bienvenida con el más cálido aplauso!",
  ui_story_31210602_75_dialog_content = "¡Alabemos a la Diosa del Espino Ardiente! ¡Alabemos al Pastor!",
  ui_story_31210602_76_dialog_content = "Gracias a todos por venir a nuestra ceremonia mensual de ofrendas. La todopoderosa Diosa Espino de Fuego espera con ansias recibir las ofrendas puras que han reunido aquí para ofrecer.",
  ui_story_31210602_77_dialog_content = "(¿Ofrendas puras? ¿Se refiere a oro y joyas o algo así?)",
  ui_story_31210602_78_dialog_content = "Su Santidad, por favor permítame decir algunas palabras. Acabamos de evaluar las ofrendas traídas por varios de los recién llegados y las hemos encontrado muy insuficientes.",
  ui_story_31210602_79_dialog_content = "Pero no quiero ser demasiado duro con ellos. Obviamente, no han logrado entender las reglas de la ceremonia y necesitan tiempo para adaptarse a nuestras costumbres.",
  ui_story_31210602_80_dialog_content = "Ahora, comenzaremos nuestra presentación de las verdaderas ofertas. ¡Mira!",
  ui_story_31210602_81_dialog_content = "Oh, esto es asombroso.",
  ui_story_31210602_82_dialog_content = "La iluminación y composición son impecables, ¡casi perfectas!",
  ui_story_31210602_83_dialog_content = "¡También he preparado una ofrenda para la Diosa del Espino de Fuego! ¡Estas son fotos espontáneas que tomé de varias chicas en la playa!",
  ui_story_31210602_84_dialog_content = "¡Wow! ¡Solo mira tus ofrendas! ¡Realmente son algo especial! ¡A la Diosa Espino de Fuego le van a encantar!",
  ui_story_31210602_85_dialog_content = "¡Esto es asqueroso! ¡Estos tipos no son más que mirones! ¡Qué grupo de pervertidos!",
  ui_story_31210602_86_dialog_content = "Pastor, ¡por favor! ¡Permítanos contemplar a la Diosa del Espino Ardiente una vez más!",
  ui_story_31210602_87_dialog_content = "Muy bien. Ha llegado el momento de invitar a la Diosa al altar para que todos ustedes la adoren.",
  ui_story_31210602_88_dialog_content = "Saludos, Diosa—",
  ui_story_31210602_89_dialog_content = "¿Eh? La Diosa del Espino de Fuego es... ¿una foto?",
  ui_story_31210602_90_dialog_content = "¿Qué son estas líneas negras entrecruzadas en la foto? No lo entiendo, pero de alguna manera me parece familiar...",
  ui_story_31210602_91_dialog_content = "¡Entonces, fue él!",
  ui_story_31210602_92_dialog_content = "¿Eh? ¿Encontraste algo?",
  ui_story_31210602_93_dialog_content = "Mis espinas pronto ahogarán la vida de este templo roto del deseo y el pecado.",
  ui_story_31210602_94_dialog_content = "Sangre fresca, ¿ya entiendes qué tipo de fotos debes tomar?",
  ui_story_31210602_95_dialog_content = "Bueno, esto es bastante extraño, pero parece muy emocionante al mismo tiempo. ¡Estoy dispuesto a unirme!",
  ui_story_31210602_96_dialog_content = "Me siento un poco avergonzado debido a mis años avanzados, pero también estoy dispuesto a seguir al Pastor y a la Diosa del Espino de Fuego!",
  ui_story_31210602_97_dialog_content = "¿Por qué esos dos recién llegados en la esquina no dicen nada? Aún no has presentado ninguna ofrenda, ¿verdad? Ahora puedes dejar que el Pastor te guíe personalmente.",
  ui_story_31210602_98_dialog_content = "Oh no, nos han notado.",
  ui_story_31210602_99_dialog_content = "Aquí, puedes tomar esta foto como ofrenda.",
  ui_story_31210602_100_dialog_content = "¿Mmm? ¿No es eso—!",
  ui_story_31210602_101_dialog_content = "¡Apúrate ahora! ¡No pierdas el tiempo del Pastor!",
  ui_story_31210602_102_dialog_content = "Ehm, yo... Esta foto...",
  ui_story_31210602_103_dialog_content = "Déjeme ver-",
  ui_story_31210602_104_dialog_content = "¿No es esta la Diosa del Espino Ardiente?!",
  ui_story_31210602_105_dialog_content = "¿Quién eres? ¿Cómo es posible que tengas una foto de la Diosa del Espino de Fuego?!",
  ui_story_31210602_106_dialog_content = "¿Sabes dónde podemos encontrar a la Diosa del Espino Ardiente? ¡Alguien! ¡Cualquiera! ¡Atrápenlo!",
  ui_story_31210602_107_dialog_content = "No sé nada...",
  ui_story_31210602_108_dialog_content = "<color=#e8d9bb>¡Swoosh! ¡Smack!</color>",
  ui_story_31210602_109_dialog_content = "¡Cómo te atreves a ponerle las manos encima!",
  ui_story_31210602_110_dialog_content = "¡Santo cielo! ¡Es la Diosa del Espino de Fuego! ¡Ha descendido!",
  ui_story_31210602_111_dialog_content = "(¿Cómo Paloma cambió su ropa tan rápido?)",
  ui_story_31210602_112_dialog_content = "Es hora de que termine esta farsa absurda.",
  ui_story_31210602_113_dialog_content = "¡Urgh! ¡Qué espinas tan feroces! ¿Podría ser esta la verdadera naturaleza de la Diosa del Espino Ardiente a la que rezo?",
  ui_story_31210602_114_dialog_content = "Diosa, ¡soy tu seguidor más leal! ¡Es el mayor honor estar en tu presencia!",
  ui_story_31210602_115_dialog_content = "¡Cierra la trampa!",
  ui_story_31210602_116_dialog_content = "¡Aaaaaahhhh!",
  ui_story_31210602_117_dialog_content = "¿Es así como deben llevarse la Diosa y el Pastor? Todo esto parece un poco demasiado intenso para mí...",
  ui_story_31210602_118_dialog_content = "Eso no es todo. Ella es mi amiga, no la Diosa de su retorcida secta. Todos han sido engañados por el Pastor.",
  ui_story_31210602_119_dialog_content = "¡Me duele, me duele! ¡Creo que estoy a punto de morir!",
  ui_story_31210602_120_dialog_content = "¿Estás dispuesto a revelar la verdad detrás de esta supuesta secta ahora? Cuéntamelo desde el principio.",
  ui_story_31210602_121_dialog_content = "*Sollozando* ¡Te lo diré! ¡Te diré todo!",
  ui_story_31210602_122_dialog_content = "Esta secta era originalmente una sociedad de fotografía de vida marina. Yo era solo uno de los miembros, pero mi verdadero interés es difícil de expresar...",
  ui_story_31210602_123_dialog_content = "Bajo mi influencia, este pequeño club se transformó lentamente en una asamblea excéntrica.",
  ui_story_31210602_124_dialog_content = "Hace unos meses, en la playa, te tomé una foto usando un traje de baño divino, y desde entonces he deseado verla de nuevo.",
  ui_story_31210602_125_dialog_content = "Cuando presenté tu foto en nuestra reunión de fotografía, todos comenzaron a maravillarse con tu belleza divina, como la de una diosa.",
  ui_story_31210602_126_dialog_content = "Luchaba con problemas de dinero en aquel momento... Bueno, no, quería cobrar a los miembros, p-para mantener el desarrollo de la sociedad!",
  ui_story_31210602_127_dialog_content = "Entonces utilicé tus fotos para crear una serie de relatos sobre la Diosa del Espino de Fuego, y gradualmente se convirtió en lo que tenemos hoy...",
  ui_story_31210602_128_dialog_content = "Tal historia detrás de la fundación de la Iglesia. Necesito registrarla en el Libro de Doctrinas para los futuros creyentes...",
  ui_story_31210602_129_dialog_content = "<color=#e8d9bb>¡Swoosh! ¡Smack!</color>",
  ui_story_31210602_130_dialog_content = "¡Oh, no! ¡El Libro de Doctrinas ha sido destrozado en pedazos!",
  ui_story_31210602_131_dialog_content = "<color=#e8d9bb>¡Swoosh! ¡Smack!</color>",
  ui_story_31210602_132_dialog_content = "¡Urgh! ¡Qué golpiza tan salvaje! ¡Qué dolor!",
  ui_story_31210602_133_dialog_content = "<color=#e8d9bb>¡Swoosh! ¡Smack!</color>",
  ui_story_31210602_134_dialog_content = "Diosa, ¡calma tu rabia! Por favor, Diosa, ¡deja de azotarme! ¡Ahhhh!",
  ui_story_31210602_135_dialog_content = "<color=#e8d9bb>¡Swoosh! ¡Smack!</color>",
  ui_story_31210602_136_dialog_content = "El deseo vergonzoso ha consumido tu alma y razón. Tus llamadas doctrinas son solo una máscara de hipocresía.",
  ui_story_31210602_137_dialog_content = "Si continúas con esta perversión descarada, ¡el verdadero juicio te desgarrará sin piedad!",
  ui_story_31210602_138_dialog_content = "¡Ahh! ¡Basta con los latigazos! No tomaremos más fotos furtivas de chicas guapas, lo juro por el Fireth—No, ¡lo juro por el Dios de la Luz!",
  ui_story_31210602_139_dialog_content = "¡Juro por el Dios de la Luz! ¡Nunca volveré a hacer algo así!",
  ui_story_31210602_140_dialog_content = "Oh, así que todos son de Lumopolis, eso explica mucho.",
  ui_story_31210602_141_dialog_content = "Uf, finalmente entregamos a esos desgraciados al Salón de Justicia.",
  ui_story_31210602_142_dialog_content = "Paloma mencionó querer ir a la playa para relajarse. Debería ir a buscarla... Tal vez necesite un poco de ánimo después de todo lo sucedido.",
  ui_story_31210602_143_dialog_content = "(¿Paloma está... observando una pequeña estrella de mar?)",
  ui_story_31210602_144_dialog_content = "(Por la expresión de felicidad en su rostro, parece que disfruta estar sola. Será mejor no molestarla.)",
  ui_story_31210602_145_dialog_content = "¿Viniste todo el camino hasta aquí solo para salir?",
  ui_story_31210602_146_dialog_content = "No quería molestarte, así que...",
  ui_story_31210602_147_dialog_content = "¿Se ha encargado de todo?",
  ui_story_31210602_148_dialog_content = "Sí, el Salón de Justicia ya ha comenzado la investigación.",
  ui_story_31210602_149_dialog_content = "Muchas gracias por todo. Soy afortunado de tenerte cerca para ayudarme a lidiar con la insoportable molestia de tratar con el Salón de Justicia.",
  ui_story_31210602_150_dialog_content = "¿Para qué son los amigos? ¿Te sientes mejor ahora?",
  ui_story_31210602_151_dialog_content = "Parece que me malinterpretas. ¿Realmente me ves como el tipo de persona que se altera fácilmente por asuntos tan triviales?",
  ui_story_31210602_152_dialog_content = "No, es solo que a la mayoría de las personas no les gustaría lo que sucedió.",
  ui_story_31210602_153_dialog_content = "Por supuesto, especialmente las chicas que fueron violadas.",
  ui_story_31210602_154_dialog_content = "Originalmente pretendían disfrutar de una estancia paradisíaca aquí, pero fueron maliciosamente violados por malhechores insidiosos.",
  ui_story_31210602_155_dialog_content = "Sí... Menos mal que atrapaste a los malos antes de que esas fotos se volvieran virales.",
  ui_story_31210602_156_dialog_content = "Even si las fotos se difundieran por todo el continente, no son esas chicas las que deberían sentir vergüenza y arrepentimiento, y sufrir consecuencias tan escandalosas.",
  ui_story_31210602_157_dialog_content = "Tengo curiosidad... ¿Qué opinas de esas personas?",
  ui_story_31210602_158_option_content = "Son solo un conjunto de criaturas patéticas, dominadas por deseos básicos.",
  ui_story_31210602_159_option_content = "¡Esos chicos son tan brutos! ¡Qué asco!",
  ui_story_31210602_160_dialog_content = "Forjaron una máscara de hipocresía en nombre de una deidad falsa para cubrir su propia fealdad y desprecio.",
  ui_story_31210602_161_dialog_content = "La religión se supone que es pura y edificante, con ideales elevados y esperanzas inspiradoras para el futuro, pero a menudo es utilizada por los malvados para envenenar el mundo.",
  ui_story_31210602_162_dialog_content = "¡Hmn! ¡Muy cierto!",
  ui_story_31210602_163_dialog_content = "Para ser honesto, no entiendo del todo todas esas grandes ideas. En realidad, todavía estoy un poco preocupado por ti y esas fotos que ese chico tomó de ti...",
  ui_story_31210602_164_dialog_content = "¿Por qué te preocuparías por mí? No hice nada malo.",
  ui_story_31210602_165_dialog_content = "Nunca dejaría que algo así me afectara. No hay nada malo en lo que visto, y me siento magnífico.",
  ui_story_31210602_166_dialog_content = "En cuanto a esos malhechores descarados, ¡los derrotaré con honor e integridad, cada vez!",
  ui_story_31210602_167_dialog_content = "¡Y eso es exactamente lo que hiciste!",
  ui_story_31210602_168_dialog_content = "Por cierto, esta foto que me diste antes... ¿La quieres de vuelta?",
  ui_story_31210602_169_dialog_content = "Es un selfie mío usando un traje de baño. ¿Te parece poco atractivo?",
  ui_story_31210602_170_dialog_content = "Claro que no. Te ves tan hermosa y segura en esta foto.",
  ui_story_31210602_171_dialog_content = "¡Piensa en ello como un regalo de un amigo!",
  ui_story_31210602_172_dialog_content = "(Esta foto de Paloma frente a la cámara tan atrevida es simplemente impresionante... Es un millón de veces más hermosa que las que se tomaron sin su conocimiento desde las sombras...)",
  ui_story_31210602_173_dialog_content = "(Si tan solo hubiera alguna forma de evitar que la gente haga cosas así... Maytal vez pueda discutir este problema con Paloma en el futuro...)"
}
return config
